import{_ as o,C as a,c as p,o as r,aa as c,G as t}from"./chunks/framework.Cn7WEiMX.js";const n="/assets/luckperms-web-editor-menu.ezsPFZM-.png",d="/assets/luckperms-web-editor-create-group.CE8X7OPJ.png",f=JSON.parse('{"title":"LuckPerms 月卡权限、指定时间段权限","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/guide"},{"title":"advanced","link":""},{"title":"LuckPerms 月卡权限、指定时间段权限","link":"/guide/advanced/luckperms-temp-permissions-example"}]},"headers":[],"relativePath":"guide/advanced/luckperms-temp-permissions-example.md","filePath":"guide/advanced/luckperms-temp-permissions-example.md"}'),l={name:"guide/advanced/luckperms-temp-permissions-example.md"};function m(u,e,g,h,k,b){const s=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return r(),p("div",null,[e[0]||(e[0]=c('<h1 id="luckperms-月卡权限、指定时间段权限" tabindex="-1">LuckPerms 月卡权限、指定时间段权限 <a class="header-anchor" href="#luckperms-月卡权限、指定时间段权限" aria-label="Permalink to &quot;LuckPerms 月卡权限、指定时间段权限&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">提示</p><p>浏览本章节视作你已经学会了 LuckPerms 部分最基础的操作。</p></div><h2 id="月卡权限" tabindex="-1">月卡权限 <a class="header-anchor" href="#月卡权限" aria-label="Permalink to &quot;月卡权限&quot;">​</a></h2><p>首先，使用 <code>/lp editor</code> 打开编辑器，在编辑器左侧点击新建权限组，名称随意。本示例将以 <code>monthly_perk</code> 为例。</p><figure><img src="'+n+'" alt="" tabindex="0"><figcaption>点击第二个加号，创建新的权限组。</figcaption></figure><figure><img src="'+d+'" alt="" tabindex="0"><figcaption>按图中例子填写。</figcaption></figure><p>随后，通过编辑器向组内添加一系列你需要让月卡组拥有的权限。</p><p>这样，月卡组的基本功能就已经做好了。</p><p>之后，找到配置文件 <code>config.yml</code> 中的 <a href="./../../wiki/LuckPerms/configuration#temporary-add-behaviour"><code>temporary-add-behaviour</code></a>，将其改为 <code>accmulate</code>（取决于你想让玩家能够连续续费，还是月卡结束时才可以再次购买）</p><p>最后，通过<a href="./../../wiki/LuckPerms/command-usage/parent#lp-usergroup-玩家权限组-parent-addtemp-权限组-时间-施加模式-情境">临时继承命令</a>，为玩家临时继承这个权限组。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp user &lt;玩家&gt; parent addtemp monthly_perk 1mo accmulate</span></span></code></pre></div><h2 id="指定时间段权限" tabindex="-1">指定时间段权限 <a class="header-anchor" href="#指定时间段权限" aria-label="Permalink to &quot;指定时间段权限&quot;">​</a></h2><p>这个功能还是要用到 LuckPerms。除此之外还需要一个任意的，支持指定时间点触发的定时命令。</p><p>这里将以 <a href="./../../wiki/CommandTimer/">CommandTimer</a> 为例。</p><p>首先，确定好限时权限的开始和结束时间。比如，我希望 <code>permission.test.a</code> 权限在每天 <code>0:00-1:00</code> 时有效，持续一小时。那么，我们就可以把问题简化为：在 0:00 时给予持续时间为一小时的对应权限。</p><p>因此，我们可以这么做：</p><p>打开 CommandTimer 的配置界面，设置定时执行（0:00），命令如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp group default permission settemp permission.test.a true 1h</span></span></code></pre></div>',18)),t(s),t(i)])}const v=o(l,[["render",m]]);export{f as __pageData,v as default};
